      }

      // Animate lightning bolt
      if (l.mesh) {
        l.mesh.visible = true;
        // Pulse effect
        const scale = 1 + Math.sin(time * 30) * 0.2;
        l.mesh.scale.set(scale, 1, scale);
      }
    }

    state.lightning = state.lightning.filter(l => l.active);
  }

